<?php

namespace Tests\Feature;

use Dedoc\Scramble\Scramble;
use Illuminate\Foundation\Testing\RefreshDatabase;
use Tests\TestCase;

/** docs/openapi.json is generated by Scramble and committed; this fails when it no longer matches the code. */
class OpenApiSpecTest extends TestCase
{
    // Scramble reads column types from the database, so the schema must exist.
    use RefreshDatabase;

    public function test_committed_openapi_spec_matches_the_code(): void
    {
        if (! class_exists(Scramble::class)) {
            $this->markTestSkipped('Scramble (dev dependency) is not installed.');
        }

        $fresh = tempnam(sys_get_temp_dir(), 'openapi');
        $this->artisan('scramble:export', ['--path' => $fresh])->assertSuccessful();

        $this->assertJsonFileEqualsJsonFile(
            base_path('docs/openapi.json'),
            $fresh,
            'docs/openapi.json is out of date. Regenerate it: docker compose exec app php artisan scramble:export',
        );
        @unlink($fresh);
    }

    public function test_spec_documents_every_api_route(): void
    {
        $spec = json_decode((string) file_get_contents(base_path('docs/openapi.json')), true);
        $documented = [];
        foreach ($spec['paths'] as $path => $operations) {
            foreach (array_keys($operations) as $method) {
                $documented[] = strtoupper($method).' '.$path;
            }
        }

        $routes = collect(app('router')->getRoutes()->getRoutes())
            ->filter(fn ($r) => str_starts_with($r->uri(), 'api/'))
            ->flatMap(fn ($r) => collect($r->methods())->reject(fn ($m) => $m === 'HEAD')
                ->map(fn ($m) => $m.' '.preg_replace('~^api/~', '/', $r->uri())))
            ->sort()->values()->all();

        $this->assertEqualsCanonicalizing($routes, $documented);
        $this->assertSame(['https://moviemov.id/api', 'http://localhost:8000/api'], array_column($spec['servers'], 'url'));
    }
}
